final class Downloader: NSObject, URLSessionDownloadDelegate {
  static let shared = Downloader()
  var backgroundCompletion: (() -> Void)?

  private lazy var session: URLSession = {
    let config = URLSessionConfiguration.background(withIdentifier: "com.example.downloads")
    config.isDiscretionary = false
    config.sessionSendsLaunchEvents = true
    return URLSession(configuration: config, delegate: self, delegateQueue: nil)
  }()

  func start(_ url: URL) {
    session.downloadTask(with: url).resume()
  }

  func urlSession(_ session: URLSession,
                  downloadTask: URLSessionDownloadTask,
                  didFinishDownloadingTo location: URL) {
    // Must move it here — the file is gone when this returns
    let destination = URL.documentsDirectory.appending(path: location.lastPathComponent)
    try? FileManager.default.moveItem(at: location, to: destination)
  }

  func urlSessionDidFinishEvents(forBackgroundURLSession session: URLSession) {
    DispatchQueue.main.async { self.backgroundCompletion?(); self.backgroundCompletion = nil }
  }
}

