final class HTTPService {
  static let shared = HTTPService()
  private let session: URLSession

  private init() {
    let config = URLSessionConfiguration.default
    config.timeoutIntervalForRequest = 15
    config.timeoutIntervalForResource = 60
    session = URLSession(configuration: config)   // no delegate -> nothing retained
  }

  func load(_ request: URLRequest, watching progress: Progress) async throws -> Data {
    // iOS 15+: the task holds this delegate only until it completes
    try await session.data(for: request, delegate: progress).0
  }

  // A session built WITH a delegate must be invalidated explicitly — deinit will
  // never run for you, because the session is holding the delegate that owns it.
  func shutDown() { session.finishTasksAndInvalidate() }
}

