// Keep the good elements instead of losing the array
struct Lossy<Element: Decodable>: Decodable {
  let elements: [Element]
  private struct Discard: Decodable {}

  init(from decoder: Decoder) throws {
    var container = try decoder.unkeyedContainer()
    var kept: [Element] = []
    while !container.isAtEnd {
      do {
        kept.append(try container.decode(Element.self))
      } catch {
        // A failed decode does NOT advance currentIndex — consume the element
        // or this loop never ends.
        _ = try? container.decode(Discard.self)
        Metrics.droppedRow(describe(error))
      }
    }
    elements = kept
  }
}

func describe(_ error: Error) -> String {
  guard let error = error as? DecodingError else { return "\(error)" }
  switch error {
  case .keyNotFound(let key, let ctx):
    return "missing '\(key.stringValue)' at \(ctx.codingPath.map(\.stringValue))"
  case .typeMismatch(_, let ctx), .valueNotFound(_, let ctx), .dataCorrupted(let ctx):
    return "\(ctx.debugDescription) at \(ctx.codingPath.map(\.stringValue))"
  @unknown default:
    return "\(error)"
  }
}

struct Row: Decodable { let id: String; let amount: Decimal }

func importRows(from url: URL, session: URLSession, store: RowStore) async throws {
  let (bytes, response) = try await session.bytes(from: url)
  guard let http = response as? HTTPURLResponse, http.statusCode == 200 else {
    throw URLError(.badServerResponse)          // check before consuming
  }

  let decoder = JSONDecoder()
  var batch: [Row] = []
  batch.reserveCapacity(500)

  // One line in memory at a time; the transfer paces itself to this loop
  for try await line in bytes.lines {
    guard !line.isEmpty else { continue }
    batch.append(try decoder.decode(Row.self, from: Data(line.utf8)))
    if batch.count == 500 {
      try await store.insert(batch)             // off the main actor
      batch.removeAll(keepingCapacity: true)
    }
  }
  if !batch.isEmpty { try await store.insert(batch) }
}

