@MainActor
final class SessionOwner {
  private(set) var http = SessionOwner.makeSession()

  private static func makeSession() -> URLSession {
    let config = URLSessionConfiguration.default
    config.urlCache = URLCache(memoryCapacity: 16 << 20, diskCapacity: 128 << 20)
    return URLSession(configuration: config)
  }

  func logOut() async {
    // 1. Stop work in flight first: a response landing after logout would be
    //    written into the next user's store.
    http.invalidateAndCancel()

    // 2. Then everything the old session owned
    let config = http.configuration            // a copy, same storage objects
    config.urlCache?.removeAllCachedResponses()
    if let jar = config.httpCookieStorage {
      jar.cookies?.forEach(jar.deleteCookie)
    }
    for (space, credentials) in URLCredentialStorage.shared.allCredentials {
      for credential in credentials.values {
        URLCredentialStorage.shared.remove(credential, for: space)
      }
    }

    // Keeping the session instead? await http.reset() does cache, cookies and
    // credentials in one call — but it will not cancel anything.

    Keychain.deleteTokens()
    await localStore.deleteEverything()
    http = SessionOwner.makeSession()          // fresh pool, fresh cache
  }
}

typealias Send = @Sendable (URLRequest) async throws -> (Data, HTTPURLResponse)

protocol HTTPMiddleware: Sendable {
  func intercept(_ request: URLRequest, next: Send) async throws -> (Data, HTTPURLResponse)
}

struct AuthMiddleware: HTTPMiddleware {
  let tokens: TokenStore                       // an actor

  func intercept(_ request: URLRequest, next: Send) async throws -> (Data, HTTPURLResponse) {
    var request = request
    request.setValue("Bearer \(await tokens.access())", forHTTPHeaderField: "Authorization")
    let (data, response) = try await next(request)
    guard response.statusCode == 401 else { return (data, response) }

    // The refresh call goes to the transport directly — routing it through
    // next() would re-enter this middleware and loop.
    var retried = request
    retried.setValue("Bearer \(try await tokens.refresh())", forHTTPHeaderField: "Authorization")
    return try await next(retried)
  }
}

struct HTTPClient: Sendable {
  private let send: Send

  init(session: URLSession, middleware: [HTTPMiddleware]) {
    let transport: Send = { request in
      let (data, response) = try await session.data(for: request)
      return (data, response as! HTTPURLResponse)
    }
    // Fold from the back so middleware[0] becomes the OUTERMOST layer
    send = middleware.reversed().reduce(transport) { next, layer in
      { request in try await layer.intercept(request, next: next) }
    }
  }

  func data(for request: URLRequest) async throws -> (Data, HTTPURLResponse) {
    try await send(request)
  }
}

