                  task: URLSessionTask,
                  willPerformHTTPRedirection response: HTTPURLResponse,
                  newRequest request: URLRequest) async -> URLRequest? {
    // 301/302/303 have ALREADY rewritten POST -> GET and dropped the body.
    // Refuse, so the caller sees the 3xx instead of a silently wrong call.
    if task.originalRequest?.httpMethod == "POST",
       [301, 302, 303].contains(response.statusCode) {
      return nil
    }

    // Never carry credentials to a host that is not ours
    var request = request
    if request.url?.host() != apiHost {
      request.setValue(nil, forHTTPHeaderField: "Authorization")
    }
    return request
  }
}

var login = URLRequest(url: URL(string: "https://api.example.com/login")!)
login.httpMethod = "POST"
login.httpBody = try JSONEncoder().encode(credentials)
login.setValue("application/json", forHTTPHeaderField: "Content-Type")

// Per-task delegate: an async call can still take part in the decision
let (data, response) = try await session.data(for: login, delegate: RedirectPolicy())
guard let http = response as? HTTPURLResponse else { throw URLError(.badServerResponse) }
if (300..<400).contains(http.statusCode) {
  throw APIError.unexpectedRedirect(http.value(forHTTPHeaderField: "Location"))
}
